SELECT
  SUM(vm.value) AS total_habits,
  SUM(ao.value) AS total_sessions
FROM (
  SELECT activity__active_date__day, value FROM "query_metric_value_moments_last_week"
) vm
JOIN (
  SELECT activity__active_date__day, value FROM "query_metric_app_opens_last_week"
) ao
ON vm.activity__active_date__day = ao.activity__active_date__day;

SELECT SUM(value) AS signups_q1_2026
FROM (
  SELECT value
  FROM TABLE(r3)
) t;
